1	import Link from "next/link";
2	import { HomeLiquidity } from "./account-liquidity-summary";
3	import { DatedOverview } from "./dated-overview";
4	import { ManualBalanceForm } from "./manual-balance-form";
5	import { ImportantInsights, loadInsightEvidence } from "./insights/panel";
6	import { Figure, Kpi, KpiFallback, MonthSpendingKpi, RecentTransactions, SectionFallback, SpendingPanel, card } from "./home-sections";
7	import { Suspense, type ReactNode } from "react";
8	import { dashboardItems, dashboardLayoutSchema } from "@/lib/finance/dashboard";
9	import { loadHomeSpending } from "@/lib/finance/dashboard-spending";
10	import { redirect } from "next/navigation";
11	import { requireWorkspace } from "@/lib/auth";
12	import { getSupabaseConfig } from "@/lib/env";
13	import { convertFx, minorDigits } from "@/lib/finance/fx";
14	import { createAccount } from "./actions";
15	import { loadBalanceEvidence, resolveBalances } from "@/lib/finance/balances";
16	import { calendarDate } from "@/lib/finance/calendar";
17	import { describeMissingInputs, formatMoney } from "@/lib/finance/format";
18	import { evaluatePlanForWorkspace } from "@/lib/finance/model";
19	import { SourceCoverageDetails } from "./source-coverage";
20	import { AgentBriefing } from "./agent-briefing";
21	import { AskAbout } from "@/components/ask-about";
22	import { loadSourceCoverageMetadata } from "@/lib/finance/source-coverage";
23	import { loadWealthItems, wealthEvidence } from "@/lib/finance/wealth";
24	import { LayoutGrid, Plus, Sparkle } from "lucide-react";
25	
26	// The design pairs a wide card with a narrow one; dense flow fills the gaps whatever order the layout picks.
27	const FULL = new Set(["overview"]);
28	const WIDE = new Set(["spending", "accounts", "insights", "recent"]);
29	
30	export default async function Home({ searchParams }: { searchParams?: Promise<{ account?: string; month?: string }> } = {}) {
31	  const params = await searchParams;
32	  const accountId = typeof params?.account === "string" ? params.account : undefined;
33	  const supabaseConfig = getSupabaseConfig();
34	  if (supabaseConfig.status !== "configured") return <main className="mx-auto max-w-3xl p-8">{supabaseConfig.detail}</main>;
35	  let context: Awaited<ReturnType<typeof requireWorkspace>>;
36	  try {
37	    context = await requireWorkspace();
38	  } catch {
39	    redirect("/login");
40	  }
41	  const { supabase, workspace } = context;
42	  const displayCurrency: string = workspace.display_currency;
43	  const locale = workspace.locale;
44	  const money = (amount: bigint | string | number, currency: string) => formatMoney(amount, currency, locale);
45	  const today = calendarDate(new Date(), workspace.timezone);
46	  const balanceEvidencePromise = loadBalanceEvidence(supabase, workspace.id);
47	  const wealthPromise = loadWealthItems(supabase, workspace.id);
48	  const sourceMetadataPromise = loadSourceCoverageMetadata(supabase, workspace.id, true);
49	  // Start the streamed sections' reads now (memoized); their Suspense boundaries pick up the same promises.
50	  loadInsightEvidence(supabase, workspace.id, displayCurrency, today).catch(() => undefined);
51	  loadHomeSpending(supabase, workspace.id, displayCurrency, today).catch(() => undefined);
52	  const [balanceEvidence, projection, wealthItems, rates, layout, goals, allocations, sourceMetadata] = await Promise.all([
53	    balanceEvidencePromise,
54	    evaluatePlanForWorkspace(supabase, workspace, 30, undefined, { balanceEvidence: balanceEvidencePromise, wealth: wealthPromise, sourceMetadata: sourceMetadataPromise }),
55	    wealthPromise,
56	    supabase.from("fx_rates").select("from_currency, to_currency, rate_text, rate_date, source")
57	      .eq("workspace_id", workspace.id).eq("to_currency", displayCurrency).order("rate_date", { ascending: false }).order("created_at", { ascending: false }),
58	    supabase.from("dashboard_layouts").select("items, version").eq("workspace_id", workspace.id).maybeSingle(),
59	    supabase.from("goals").select("id, name, target_minor::text, currency_code, target_date").eq("workspace_id", workspace.id).eq("status", "active").order("priority").limit(10),
60	    supabase.from("goal_allocations").select("goal_id, account_id, amount_minor::text").eq("workspace_id", workspace.id),
61	    sourceMetadataPromise,
62	  ]);
63	  for (const error of [rates.error, layout.error, goals.error, allocations.error]) if (error) throw error;
64	  const accounts = resolveBalances(balanceEvidence.accounts, balanceEvidence.snapshots, balanceEvidence.ledger, balanceEvidence.asOf, workspace.timezone, sourceMetadata).filter(account => !account.archived_at);
65	  const accountNames = new Map(accounts.map(account => [account.id, account.name]));
66	  const fxRates = rates.data ?? [];
67	
68	  // Net worth: dated balances and valuations converted with the latest rate on or before each observation.
69	  const missingInputs: string[] = [];
70	  let netWorthMinor = 0n;
71	  let convertedCount = 0;
72	  // Split by sign for the hero: positive accounts, positive valuations, and everything owed.
73	  const parts = { cash: 0n, assets: 0n, debts: 0n };
74	  const addConverted = (amountMinor: bigint, from: string, asOf: string, source: string, name: string, part: "cash" | "assets") => {
75	    const rate = from === displayCurrency ? undefined : fxRates.find(row => row.from_currency === from && String(row.rate_date).slice(0, 10) <= asOf);
76	    try {
77	      const result = convertFx({ amountMinor, from, to: displayCurrency, rate: rate?.rate_text, source: rate?.source ?? source, date: rate ? String(rate.rate_date).slice(0, 10) : asOf });
78	      if (result.status === "available") {
79	        const converted = result.converted.amountMinor;
80	        netWorthMinor += converted; convertedCount += 1;
81	        parts[converted < 0n ? "debts" : part] += converted;
82	      }
83	      else missingInputs.push(...result.missingInputs.map(input => `${input} for ${name}`));
84	    } catch {
85	      missingInputs.push(`rate:${from}->${displayCurrency} for ${name}`);
86	    }
87	  };
88	  for (const account of accounts) {
89	    const { balance } = account;
90	    if (balance.amount_minor === null) { missingInputs.push(`balance:${account.name}`); continue; }
91	    addConverted(BigInt(balance.amount_minor), balance.currency_code, calendarDate(balance.as_of!, workspace.timezone), balance.provenance || "balance", account.name, "cash");
92	  }
93	  const valuations = wealthEvidence(wealthItems, today);
94	  missingInputs.push(...valuations.missingInputs);
95	  for (const valuation of valuations.included) addConverted(valuation.amountMinor, valuation.currencyCode, valuation.asOf, valuation.provenance, valuation.name, "assets");
96	
97	  const upcoming = (projection.input?.events ?? []).filter(event => event.expectedMinor < 0n && event.source !== "estimated").sort((a, b) => a.date.localeCompare(b.date));
98	  const upcomingMinor = upcoming.reduce((sum, event) => sum + event.expectedMinor, 0n);
99	  const available = projection.available;
100	  const parsedLayout = layout.data ? dashboardLayoutSchema.safeParse(layout.data.items) : null;
101	  if (parsedLayout && !parsedLayout.success) throw new Error("Dashboard preferences are invalid; review them in Settings");
102	  const ordered = dashboardItems(parsedLayout?.success ? parsedLayout.data : null);
103	  const sectionProps = { db: supabase, workspaceId: workspace.id, currency: displayCurrency, today, locale };
104	
105	  const widgets: Record<string, ReactNode> = {
106	    overview: <section aria-label="Overview" className="grid gap-4 lg:grid-cols-3">
107	      <div className={`${card} flex flex-col gap-5 lg:col-span-2`}>
108	        <div className="flex flex-wrap items-center justify-between gap-3">
109	          <div className="flex flex-wrap items-center gap-2.5"><h2 className="text-sm font-medium">Net worth</h2>
110	            {convertedCount > 0 && <span className="rounded-md border border-dashed border-input px-2 py-0.5 font-mono text-[11px] text-muted-foreground">traced · {accounts.length} accounts · {valuations.included.length} valuations</span>}</div>
111	          <Link href="/plan/currency" className="rounded-lg border border-input px-2.5 py-1 font-mono text-xs text-muted-foreground hover:text-foreground">{displayCurrency}</Link>
112	        </div>
113	        {!accounts.length && !wealthItems.length ? <p className="text-sm text-muted-foreground">Add an account to see your net worth.</p>
114	          : convertedCount > 0 ? <div className="flex flex-wrap items-baseline gap-x-4 gap-y-1"><Figure value={money(netWorthMinor, displayCurrency)} digits={minorDigits(displayCurrency)} className="display-figure text-5xl sm:text-7xl" />{missingInputs.length > 0 && <span className="font-mono text-xs text-warning">Partial</span>}</div>
115	          : <p className="text-sm text-muted-foreground">Net worth unavailable in {displayCurrency}.</p>}
116	        {missingInputs.length > 0 ? <details className="text-xs text-muted-foreground"><summary className="cursor-pointer text-brand">{convertedCount > 0 ? "Some balances or rates are missing" : "See what is missing"}</summary><ul className="mt-2 list-disc space-y-1 pl-4">{describeMissingInputs(missingInputs).map(item => <li key={item}>{item}</li>)}</ul><Link href="/money/wealth" className="mt-2 inline-block underline">Review dated valuations</Link></details>
117	          : convertedCount > 0 && <p className="-mt-2 text-xs text-muted-foreground">Includes debts and valuations.</p>}
118	        {convertedCount > 0 && <dl className="grid grid-cols-1 gap-px overflow-hidden rounded-[14px] bg-border sm:grid-cols-3">
119	          {([["Cash & accounts", parts.cash, "/money/accounts"], ["Assets", parts.assets, "/money/wealth"], ["Debts", parts.debts, "/money/wealth"]] as const).map(([label, amount, href]) =>
120	            <div key={label} className="bg-card"><Link href={href} className="flex flex-col gap-1 px-4 py-3.5 hover:bg-muted"><dt className="text-xs text-muted-foreground">{label}</dt><dd className="font-mono">{money(amount, displayCurrency)}</dd></Link></div>)}
121	        </dl>}
122	        <DatedOverview accounts={accounts} wealth={wealthItems} today={today} locale={locale} />
123	      </div>
124	      <div className={`${card} flex flex-col gap-4`}>
125	        <div className="flex items-baseline justify-between gap-2"><h2 className="text-sm font-medium">This month</h2><span className="font-mono text-[11px] text-subtle">day {Number(today.slice(8, 10))} / {new Date(Date.UTC(Number(today.slice(0, 4)), Number(today.slice(5, 7)), 0)).getUTCDate()}</span></div>
126	        <Suspense fallback={<KpiFallback label="Spent this month" />}><MonthSpendingKpi {...sectionProps} /></Suspense>
127	        <Kpi label="Upcoming payments" href="/money/recurring" action="Recurring">
128	          {upcoming.length ? <><p className="mt-1 font-mono text-xl">{money(-upcomingMinor, displayCurrency)}</p><p className="mt-1 truncate text-xs text-muted-foreground">{upcoming.length} confirmed in 30 days · next {upcoming[0].name ?? "payment"} on {upcoming[0].date}</p></>
129	            : <p className="mt-1 text-sm text-muted-foreground">No confirmed payments in the next 30 days.</p>}
130	        </Kpi>
131	        <Kpi label="Cash available" href="/plan" action="Forecast">
132	          {available?.status === "available" ? <><p className="display-figure mt-1 text-[32px]">{money(available.amountMinor, displayCurrency)}</p><p className="mt-1 text-xs text-muted-foreground">After upcoming payments and your buffer</p></>
133	            : <p className="mt-1 text-sm text-muted-foreground">Add a balance for each spending account to see this.</p>}
134	        </Kpi>
135	        {available?.status === "available" && <div className="mt-auto flex flex-col gap-1.5 rounded-[14px] border border-ai-border bg-ai-soft p-3.5">
136	          <p className="flex items-center gap-2 text-xs text-ai"><Sparkle className="size-3.5 fill-current" aria-hidden="true" />Cash-flow forecast</p>
137	          <p className="text-[13px]">Lowest point on <span className="font-mono">{available.limitingDate}</span>. <Link href="/plan" className="text-brand hover:underline">See forecast</Link></p>
138	        </div>}
139	      </div>
140	    </section>,
141	    spending: <Suspense fallback={<SectionFallback title="Spending" />}><SpendingPanel {...sectionProps} month={typeof params?.month === "string" ? params.month : undefined} /></Suspense>,
142	    recent: <Suspense fallback={<SectionFallback title="Recent transactions" />}><RecentTransactions db={supabase} workspaceId={workspace.id} locale={locale} names={accountNames} /></Suspense>,
143	    planning: projection.liquidity && <section aria-label="Available funds"><HomeLiquidity liquidity={projection.liquidity} accountId={accountId} names={accountNames} locale={locale} coverage={<SourceCoverageDetails coverage={projection.sourceCoverage} />} /></section>,
144	    accounts: <section aria-labelledby="home-accounts" className={card}>
145	      <div className="flex items-baseline justify-between gap-2"><h2 id="home-accounts" className="text-sm font-medium">Accounts</h2><span className="text-sm text-muted-foreground">{accounts.length} total</span></div>
146	      {!accounts.length && <p className="mt-3 text-sm text-muted-foreground">No accounts yet. <Link className="text-brand underline" href="/import">Import a statement</Link> or add one below.</p>}
147	      <ul className="mt-2 divide-y divide-border">{accounts.map(account => { const { balance } = account; return <li key={account.id}><article className="flex flex-wrap items-center gap-x-4 gap-y-1 py-2.5">
148	        <div className="min-w-0 flex-1"><h3 className="truncate text-sm font-medium">{account.name}</h3><p className="truncate text-xs text-muted-foreground"><span className="capitalize">{account.type}</span> · {balance.as_of ? `As of ${calendarDate(balance.as_of, workspace.timezone)} · ${balance.status.replaceAll("_", " ")}` : "Add a dated balance"}</p></div>
149	        <p className="font-mono text-sm font-semibold">{balance.snapshot_amount_minor !== null ? money(balance.snapshot_amount_minor, balance.snapshot_currency_code!) : "Balance unknown"}</p>
150	        <AskAbout label="Ask" question={`How is my ${account.name} account doing? Summarise recent activity, upcoming payments and its balance trend.`} about={{ kind: "account", id: account.id, label: account.name }} />
151	        <details className="open:w-full"><summary className="cursor-pointer text-xs font-medium text-brand hover:underline">Update balance</summary><div className="mt-2 rounded-lg border border-border p-3"><ManualBalanceForm account={account} snapshots={balanceEvidence.snapshots} ledger={balanceEvidence.ledger} asOf={balanceEvidence.asOf} timeZone={workspace.timezone} locale={locale} /></div></details>
152	        {balance.warnings.length > 0 && <p className="w-full text-xs text-warning">{balance.warnings.join("; ")}</p>}
153	        {balance.status === "stale" && balance.estimated_amount_minor !== null && <p className="w-full text-xs text-muted-foreground">Recent activity suggests about {money(balance.estimated_amount_minor, balance.currency_code)}. Update the balance to confirm.</p>}
154	      </article></li>; })}</ul>
155	      <form action={createAccount} className="mt-3 flex flex-wrap items-center gap-2 border-t border-border pt-3"><input name="name" required maxLength={120} placeholder="New account name" aria-label="Account name" className="min-h-9 min-w-36 flex-1 rounded-lg border border-border bg-card px-3 py-1.5 text-sm" /><select name="type" aria-label="Account type" className="min-h-9 rounded-lg border border-border bg-card px-2 py-1.5 text-sm"><option value="checking">Checking</option><option value="savings">Savings</option><option value="cash">Cash</option><option value="credit">Credit</option><option value="investment">Investment</option><option value="wallet">Wallet</option><option value="other">Other</option></select><input name="currency" defaultValue={displayCurrency} maxLength={3} aria-label="Currency code" className="min-h-9 w-16 rounded-lg border border-border bg-card px-2 py-1.5 text-sm" /><button className="inline-flex min-h-9 items-center gap-1 rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground"><Plus size={14} /> Add account</button></form>
156	    </section>,
157	    upcoming: <section className={card}>
158	      <div className="flex items-baseline justify-between gap-2"><h2 className="text-sm font-medium">Upcoming payments</h2><Link href="/money/recurring" className="text-sm font-medium text-brand hover:underline">Recurring</Link></div>
159	      <p className="mt-1 text-xs text-muted-foreground">Confirmed payments over the next 30 days, in {displayCurrency}.</p>
160	      {upcoming.length ? <ul className="mt-2 divide-y divide-border">{upcoming.slice(0, 8).map((event, index) => <li key={`${event.accountId}:${event.date}:${index}`} className="flex items-center gap-3 py-2 text-sm"><span className="w-20 shrink-0 font-mono text-xs text-muted-foreground">{event.date}</span><span className="min-w-0 flex-1 truncate">{event.name ?? "Confirmed payment"} <span className="text-xs text-muted-foreground">· {accountNames.get(event.accountId) ?? "Account"}</span></span><span className="shrink-0 font-mono">{money(event.expectedMinor, displayCurrency)}</span></li>)}</ul>
161	        : <p className="mt-3 text-sm text-muted-foreground">No confirmed payments in this forecast.</p>}
162	    </section>,
163	    goals: <section className={card}>
164	      <div className="flex items-baseline justify-between gap-2"><h2 className="text-sm font-medium">Goals</h2><Link href="/plan" className="text-sm font-medium text-brand hover:underline">Plan</Link></div>
165	      <p className="mt-1 text-xs text-muted-foreground">Reserving money for a goal does not move it.</p>
166	      <ul className="mt-2 divide-y divide-border">{(goals.data ?? []).map(goal => { const reservations = (allocations.data ?? []).filter(row => row.goal_id === goal.id); const comparable = reservations.every(row => accounts.find(account => account.id === row.account_id)?.currency_code === goal.currency_code); const reserved = reservations.reduce((sum, row) => sum + BigInt(row.amount_minor), 0n); return <li key={goal.id} className="py-2 text-sm"><Link href="/plan" className="font-medium hover:underline">{goal.name}</Link><p className="text-xs text-muted-foreground">{comparable ? money(reserved, goal.currency_code) : "Reservation conversion required"} reserved of {money(goal.target_minor, goal.currency_code)}{goal.target_date ? ` · target ${goal.target_date}` : ""}</p></li>; })}</ul>
167	      {!goals.data?.length && <p className="mt-3 text-sm text-muted-foreground">No goals yet. <Link href="/plan" className="underline">Create a goal</Link>.</p>}
168	    </section>,
169	    insights: <Suspense fallback={<SectionFallback title="Important insights" />}>
