5	export function DatedOverview({accounts, wealth, today, locale}: {
6	  accounts: ReturnType<typeof resolveBalances>; wealth: WealthValue[]; today: string; locale: string;
7	}) {
8	  const valuations = wealthEvidence(wealth, today, "observed");
9	  const observations = accounts.filter(account => !account.archived_at && account.balance.snapshot_valid && account.balance.snapshot_amount_minor !== null)
10	    .map(account => ({id: `account:${account.id}`, name: account.name, amount: BigInt(account.balance.snapshot_amount_minor!),
11	      currency: account.balance.snapshot_currency_code!}));
12	  observations.push(...valuations.included.map(value => ({id: `wealth:${value.id}`, name: value.name, amount: value.amountMinor,
13	    currency: value.currencyCode})));
14	  const totals = new Map<string, bigint>();
15	  for (const observation of observations) totals.set(observation.currency, (totals.get(observation.currency) ?? 0n) + observation.amount);
16	  return <details className="border-t border-border pt-3 text-sm">
17	    <summary className="cursor-pointer text-xs font-medium text-muted-foreground hover:text-foreground">Recorded net worth by currency</summary>
18	    <ul className="mt-3 space-y-1">{[...totals].map(([currency, amount]) => <li key={currency} className="font-mono font-semibold">{formatMoney(amount, currency, locale)}</li>)}</ul>
19	    <ul className="mt-3 divide-y divide-border">{observations.map(row => <li key={row.id} className="flex justify-between gap-3 py-2"><span className="truncate">{row.name}</span><span className="shrink-0 font-mono">{formatMoney(row.amount, row.currency, locale)}</span></li>)}</ul>
20	  </details>;
21	}
